import{mkdir,readFile,readdir,rm,writeFile}from"node:fs/promises";import{join}from"node:path";import{stopDevelopmentSandboxResources}from"#execution/sandbox/bindings/local.js";const PREFIX=`dev-cleanup-intent.`,SUFFIX=`.json`;async function recordCleanupIntent(e,t){let n=join(e,`.eve`),r=join(n,`${PREFIX}${t.runId}${SUFFIX}`);return await mkdir(n,{recursive:!0}),await writeFile(r,`${JSON.stringify(t)}\n`,`utf8`),async()=>await rm(r,{force:!0})}async function reconcileCleanupIntents(e){let t=join(e,`.eve`),n;try{n=await readdir(t)}catch(e){if(e instanceof Error&&`code`in e&&e.code===`ENOENT`)return;throw e}await Promise.all(n.filter(e=>e.startsWith(PREFIX)&&e.endsWith(SUFFIX)).map(async e=>{try{let n=join(t,e),r=JSON.parse(await readFile(n,`utf8`));if(typeof r.runId!=`string`||typeof r.ownerPid!=`number`||!Number.isInteger(r.ownerPid)||r.ownerPid<=0||isProcessAlive(r.ownerPid))return;await stopDevelopmentSandboxResources({devRunId:r.runId}),await rm(n,{force:!0})}catch{}}))}function isProcessAlive(e){try{return process.kill(e,0),!0}catch(e){return e instanceof Error&&`code`in e&&e.code===`EPERM`}}export{reconcileCleanupIntents,recordCleanupIntent};